with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '夜警', 'レンブラント・ファン・レイン', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg/960px-La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg', '1642年、オランダ黄金時代の絶頂期に完成したレンブラントの代表作で、アムステルダム国立美術館に展示されています。火縄銃手組合の市民隊が、フランス・バニング・コック隊長の号令で動き出す瞬間を描いた集団肖像画です。縦3メートルを超える大画面に、明暗法による強い光と影、銃を構える隊員や吠える犬、走る少年などの動きが重なり合います。『夜警』という通称は表面が茶色く変色したための誤解で、実は昼の情景です。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:La_ronda_de_noche,_por_Rembrandt_van_Rijn.jpg'),
    (2, '見返り美人図', '菱川師宣', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Hishikawa_Moronobu_-_Beauty_Looking_Back_-_Google_Art_Project.jpg/960px-Hishikawa_Moronobu_-_Beauty_Looking_Back_-_Google_Art_Project.jpg', '「浮世絵の祖」と呼ばれる菱川師宣による、絹本着色の肉筆画で、東京国立博物館が所蔵しています。紅色の地に菊と桜の刺繍をほどこした着物の女性が、歩みの途中でふと後ろを振り返る姿を描いています。この姿勢は、当時流行した「吉弥結び」の帯や衣装の美しさを見せる工夫と考えられています。1948年には切手趣味週間の切手の図案に採用され、日本の記念切手を代表する一枚として広く知られるようになりました。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Hishikawa_Moronobu_-_Beauty_Looking_Back_-_Google_Art_Project.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「MOTアニュアル2027 身を通す」開催へ', '東京都現代美術館のグループ展「MOTアニュアル2027 身を通す」が2027年2月20日から開催。4名が身体を通して記憶や経験を捉え直す。', '東京都現代美術館で、グループ展「MOTアニュアル2027 身を通す」が開催されます。会期は2027年2月20日から5月30日まで。現代美術の現在を見つめ、新たな視点を示すことを目的に同館が続けてきたグループ展で、第21回となる今回は小林勇輝、ハラサオリ、乾真裕子、筒｜tsu-tsuの4名が参加します。武術や振付、歌唱、演技といった身体的な実践を通して、過去の記憶や他者の経験を捉え直す新作を中心に、映像、インスタレーション、写真、ドローイングなどを紹介します。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33254',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
