values ('コンポジションVII', 'Composition VII', 'ワシリー・カンディンスキー', 'Wassily Kandinsky',
        1913,
        (select slug from public.art_movements where slug = 'expressionism'),
        'トレチャコフ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Composition_VII_-_Wassily_Kandinsky%2C_GAC.jpg/960px-Composition_VII_-_Wassily_Kandinsky%2C_GAC.jpg', '1913年、ミュンヘンで「青騎士」の時代にあったカンディンスキーが描いた、縦約2メートル、横約3メートルの大作で、モスクワのトレチャコフ美術館が所蔵しています。渦を巻くような色と線が画面いっぱいに広がり、具体的な形はほとんど読み取れません。研究者は、復活、最後の審判、大洪水、エデンの園といった主題が重ねられていると読み解いています。内面の感情を強い色で表す表現主義の姿勢を受け継ぎながら、目に見えるものの再現から離れ、抽象絵画へ踏み出した節目の作品です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Composition_VII_-_Wassily_Kandinsky,_GAC.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ヴァリーの肖像', 'Portrait of Wally', 'エゴン・シーレ', 'Egon Schiele',
        1912,
        (select slug from public.art_movements where slug = 'expressionism'),
        'レオポルド美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Egon_Schiele_-_Portrait_of_Wally_Neuzil_-_Google_Art_Project.jpg/960px-Egon_Schiele_-_Portrait_of_Wally_Neuzil_-_Google_Art_Project.jpg', '1912年にエゴン・シーレが、恋人でありモデルでもあったヴァリー・ノイツィルを描いた板に油彩の小品で、ウィーンのレオポルド美術館が所蔵しています。大きな目でこちらを見つめる顔が、余白の多い画面に強く浮かび上がります。1939年、ナチスから逃れようとしたユダヤ人画商の手から不本意に渡った経緯があり、1997年にニューヨークで展示された後に差し押さえられ、2010年の和解まで長い係争が続きました。クリムトの装飾性から離れ、張りつめた線で人の内面に迫る表現主義の作風がよく表れています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Egon_Schiele_-_Portrait_of_Wally_Neuzil_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
