    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('菱川師宣', 'Hishikawa Moronobu', '師宣',
        null, 1694, 'japan', array['ukiyo-e']::text[],
        '版本の挿絵を一枚の絵として独立させ、「浮世絵の祖」と呼ばれる江戸時代前期の絵師。', '安房国平郡保田村（現在の千葉県鋸南町）の縫箔師の家に生まれました。生年ははっきりせず、諸説あります。明暦の大火の後、万治年間に江戸へ出て、狩野派・土佐派・長谷川派などの技法を学び、はじめは縫箔の上絵を描いていましたが、やがて絵を本業としました。

1671年刊の噺本『私可多咄』の挿絵が初期の仕事とされ、以後、多くの絵本の挿絵を手がけました。挿絵を独立した一枚の絵として墨一色で大量に摺ることで、庶民にも手の届く美術を生み出し、浮世絵の基本の形を築きました。

肉筆画の代表作「見返り美人図」は東京国立博物館が所蔵しています。子の師房らを含む多くの門人が工房として「菱川派」を形づくりました。1694年に没しています。', 'https://ja.wikipedia.org/wiki/%E8%8F%B1%E5%B7%9D%E5%B8%AB%E5%AE%A3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('歌川国芳', 'Utagawa Kuniyoshi', '国芳',
        1798, 1861, 'japan', array['ukiyo-e']::text[],
        '躍動する武者絵と機知に富んだ戯画で人気を集めた、江戸時代末期の浮世絵師。', '1798年に江戸に生まれ、歌川豊国のもとで学びました。1820年代の終わりに出した水滸伝の豪傑たちのシリーズで一躍人気を得て、勢いのある武者絵から「武者絵の国芳」と呼ばれるようになります。

武者絵のほか、風景画、美人画、役者絵、戯画まで幅広く手がけ、輸入された西洋の版画から陰影や遠近の表し方も学びました。天保の改革で役者絵などが禁じられると、伝説の場面に見せかけて世相を風刺し、たびたび取り調べを受けています。猫を描いた作品や、人の体を寄せ集めて顔をつくる寄せ絵もよく知られています。

大きな骸骨が現れる「相馬の古内裏」や「宮本武蔵の鯨退治」など、画面を大胆に使う構図が持ち味です。門下からは月岡芳年や河鍋暁斎が出ました。1861年に没しています。', 'https://ja.wikipedia.org/wiki/%E6%AD%8C%E5%B7%9D%E5%9B%BD%E8%8A%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('クルト・シュヴィッタース', 'Kurt Schwitters', 'シュヴィッタース',
        1887, 1948, 'west', array['dada']::text[],
        '廃物を貼り合わせた「メルツ」の作品で知られる、ハノーファー出身のドイツの芸術家。', '1887年、ドイツのハノーファーに生まれました。絵画のほか、詩、音響、彫刻、グラフィックデザイン、タイポグラフィ、パフォーマンスまで幅広く手がけ、ダダイスムや構成主義などさまざまな前衛の動きに関わりました。

切符や包み紙などの廃物を用いたコラージュを「メルツ絵画」と名づけました。「メルツ」は、ある銀行名の一部の文字から取った言葉です。ベルリン・ダダの中心メンバーではありませんでしたが、各地のダダの作家と交流し、その要素を作品に取り入れました。1922年から1932年にかけては音響詩『ウルソナタ』を作り続けています。

自宅を改造した空間作品「メルツバウ」は、1943年の空襲で失われました。1937年にノルウェーへ逃れ、1940年にはイギリスへ亡命し、1948年にイギリスのケンダルで没しました。', 'https://ja.wikipedia.org/wiki/%E3%82%AF%E3%83%AB%E3%83%88%E3%83%BB%E3%82%B7%E3%83%A5%E3%83%B4%E3%82%A3%E3%83%83%E3%82%BF%E3%83%BC%E3%82%B9')
